{
  "description": "The creature is shown in right-facing side profile as a large, bear-shaped quadruped with thick, shaggy brown fur that is lighter tan on the lower belly and muzzle. Its overall body, head, legs, paws and short stub tail are those of a brown bear, but the dorsal head, neck and shoulder and the lower parts of all four legs are overlaid with glossy, hard, dark reddish-brown to black beetle exoskeleton. A very large, curved, fork-tipped beetle horn arches up and forward from the crown of the head, with a smaller forward-pointing horn below it, both emerging from a shiny carapace that sits on the bear's head and has tiny jointed insect legs gripping the fur. Additional overlapping shiny plates cover the back of the neck and shoulders, and segmented plates encircle the lower fore and hind legs. A row of small oval dark openings with pale rims runs horizontally along the lower flank in the fur.",
  "parts": [
    {
      "part": "head",
      "looks_like": "bear-like head at the right end of the body, covered in brown fur with a lighter tan muzzle, black nose and nostrils, small brown eyes, mouth closed, facing right",
      "where": "front right end of the body"
    },
    {
      "part": "horns",
      "looks_like": "one very large glossy dark brown-black curved horn with a forked tip and a small side tooth, arching up and forward, and a smaller sharp glossy horn below it pointing forward, both emerging from a shiny beetle carapace on the crown",
      "where": "on top of the head, rising from the crown"
    },
    {
      "part": "ears",
      "looks_like": "two small rounded furry brown ears with dense fur",
      "where": "on top of the head just behind the horn base, one more visible than the other"
    },
    {
      "part": "legs",
      "looks_like": "four thick muscular bear legs covered in long shaggy brown fur, with dark glossy segmented beetle-like plates encircling the lower portion of each leg",
      "where": "two front legs under the chest/shoulder and two hind legs under the hips, supporting the body"
    },
    {
      "part": "feet",
      "looks_like": "four large bear paws with broad pads and long curved light-colored claws on each toe",
      "where": "at the bottom end of each leg on the ground"
    },
    {
      "part": "tail",
      "looks_like": "very short stubby furry tail, same brown fur as body",
      "where": "at the rear left end of the body"
    },
    {
      "part": "shell_plates",
      "looks_like": "glossy hard smooth reflective dark reddish-brown to black beetle exoskeleton plates, overlapping, with pointed edges and a domed shape, covering the crown around the horns and the dorsal neck and shoulder",
      "where": "on top of the head encasing the horn bases and draped over the back of the neck and upper back/shoulder"
    },
    {
      "part": "markings",
      "looks_like": "a horizontal row of 7-8 small oval dark holes/openings with pale rims, set in the fur, resembling spiracles",
      "where": "along the lower side/flank of the torso above the lighter belly fur, between the front and hind legs"
    },
    {
      "part": "eyes",
      "looks_like": "small round brown eyes with dark pupils",
      "where": "on the side of the head, one clearly visible facing right"
    },
    {
      "part": "fur",
      "looks_like": "long thick shaggy brown fur, darker on the back and legs, lighter tan on the muzzle and underside",
      "where": "covering most of the body, head, legs and tail except where shell plates cover"
    }
  ],
  "attached_objects": [],
  "animals": [
    "bear",
    "beetle"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 4,
  "tails": 1
}
